LEVEL = 1
CFG = {1: 2, 2: 3, 3: 5}
K = CFG[LEVEL]
rows = [{"age": 34, "zip": "12345"}, {"age": 36, "zip": "12346"}, {"age": 35, "zip": "12345"}, {"age": 52, "zip": "99999"}]
def gen(r): return ("%d-%d" % (r["age"] // 10 * 10, r["age"] // 10 * 10 + 9), r["zip"][:3] + "**")
groups = {}
for r in rows: groups.setdefault(gen(r), []).append(r)
kept = {g: v for g, v in groups.items() if len(v) >= K}
print("k=%d groups kept:" % K, {g: len(v) for g, v in kept.items()}, "| suppressed:", sum(len(v) for g, v in groups.items() if len(v) < K))

